\section{Situaciones}

\begin{frame}{Situaciones: multiplicar una parte}
	\small
	\begin{columns}[T]
		\begin{column}{0.48\textwidth}
			\begin{block}{02b Tela}
				Usar la mitad de $\frac34$ m$^2$:
				\[
					\frac12\times\frac34=\frac38.
				\]
			\end{block}
			\begin{block}{03 Deuda}
				\[
					\frac34(132)=99,
					\qquad
					\frac23(99)=66,
					\qquad
					99-66=33.
				\]
			\end{block}
		\end{column}
		\begin{column}{0.48\textwidth}
			\begin{block}{10 Queso}
