\section{Situaciones}

\begin{frame}{Situaciones: multiplicar una parte}
	\small
	\begin{columns}[T]
		\begin{column}{0.48\textwidth}
			\begin{block}{02b Tela}
				Usar la mitad de $\frac34$ m$^2$:
				\[
					\frac12\times\frac34=\frac38.
